-- The built-in example reference rows for dashboard-reference-data.sql: a stack whose
-- spec.components.controlDB.referenceRows is empty seeds these. They are made up. A stack's own
-- catalog goes in that field, in the same shape (hack/export-dashboard-reference-rows.sh prints it).
-- 0d735744-e58e-4438-b618-97523e407cdc is the default plan the dashboard's migration 0008 names, so
-- it must always be present.
--
-- The example catalog is only for a new stack. A control database that already holds plans or
-- models of its own fails here, in the migration Job's transaction, and nothing is changed: set the
-- stack's spec.components.controlDB.referenceRows to its catalog instead.
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM subscription_plans WHERE id NOT IN ('0d735744-e58e-4438-b618-97523e407cdc', '00000000-0000-4000-8000-000000000002'))
    OR EXISTS (SELECT 1 FROM llms WHERE id <> '00000000-0000-4000-8000-000000000201') THEN
  RAISE EXCEPTION 'this control database has a catalog of its own: set spec.components.controlDB.referenceRows to it';
 END IF;
END $$;
